goals.implied:
∀ (f : ℝ → ℝ → ℝ),
  ((∀ (y : ℝ), Differentiable ℝ fun x => f x y) ∧ ∀ (x : ℝ), Differentiable ℝ fun y => f x y) →
    (∀ (x y : ℝ), x ^ 2 + y ^ 2 ≤ 1 → |f x y| ≤ 1) → ContinuousOn (fun p => f p.1 p.2) {p | p.1 ^ 2 + p.2 ^ 2 ≤ 1}

goals.nimplied:
¬∀ (f : ℝ → ℝ → ℝ),
    ((∀ (y : ℝ), Differentiable ℝ fun x => f x y) ∧ ∀ (x : ℝ), Differentiable ℝ fun y => f x y) →
      (∀ (x y : ℝ), x ^ 2 + y ^ 2 ≤ 1 → |f x y| ≤ 1) → ContinuousOn (fun p => f p.1 p.2) {p | p.1 ^ 2 + p.2 ^ 2 ≤ 1}

goals.implied:
∀ (contains : ℝ → Prop) (r : ℝ),
  contains r ↔
    ∃ A, ∃ C ∈ A, Module.finrank ℝ ↥A.direction = 2 ∧ sphere C r ∩ ↑A ⊆ {P | ∀ (i : Fin 4), |P.ofLp i| ≤ 1 / 2}

goals.nimplied:
¬∀ (contains : ℝ → Prop) (r : ℝ),
    contains r ↔
      ∃ A, ∃ C ∈ A, Module.finrank ℝ ↥A.direction = 2 ∧ sphere C r ∩ ↑A ⊆ {P | ∀ (i : Fin 4), |P.ofLp i| ≤ 1 / 2}

goals.implied:
∀ (n : ℕ) (S : Fin (2 ^ n - 1) → Set ℕ) (M : Matrix (Fin (2 ^ n - 1)) (Fin (2 ^ n - 1)) ℝ),
  n ≥ 1 →
    (∀ (i j : Fin (2 ^ n - 1)), M i j = if (S i ∩ S j = ∅) = True then 0 else 1) → Set.range S = 𝒫 Set.Icc 1 n \ {∅}

goals.nimplied:
¬∀ (n : ℕ) (S : Fin (2 ^ n - 1) → Set ℕ) (M : Matrix (Fin (2 ^ n - 1)) (Fin (2 ^ n - 1)) ℝ),
    n ≥ 1 →
      (∀ (i j : Fin (2 ^ n - 1)), M i j = if (S i ∩ S j = ∅) = True then 0 else 1) → Set.range S = 𝒫 Set.Icc 1 n \ {∅}
